from functools import lru_cache

# Manual memoisation with dict
def fib(n, memo=None):
    if memo is None: memo = {}
    if n <= 1: return n
    if n in memo: return memo[n]
    memo[n] = fib(n-1, memo) + fib(n-2, memo)
    return memo[n]

# Using @lru_cache decorator — automatic memoisation
@lru_cache(maxsize=None)
def fib_cached(n):
    if n <= 1: return n
    return fib_cached(n-1) + fib_cached(n-2)

print(fib_cached(100))  # 354224848179261915075

# Coin Change — minimum coins to make amount
# State: min_coins(amount)
# Recurrence: min_coins(a) = 1 + min(min_coins(a - c) for c in coins if c <= a)
@lru_cache(maxsize=None)
def min_coins(amount, coins):
    if amount == 0: return 0          # base case
    if amount < 0:  return float('inf')
    return 1 + min(min_coins(amount - c, coins)
                   for c in coins if c <= amount)

coins = (1, 5, 10, 25)
print(min_coins(41, coins))   # 4  (25+10+5+1)
print(min_coins(11, coins))   # 2  (10+1)

from functools import lru_cache

# Unique paths in m×n grid (only right or down moves)
@lru_cache(maxsize=None)
def unique_paths(m, n):
    if m == 1 or n == 1: return 1   # base: only one path along edge
    return unique_paths(m-1, n) + unique_paths(m, n-1)

print(unique_paths(3, 7))   # 28
print(unique_paths(3, 3))   # 6

# Longest Common Subsequence (LCS)
@lru_cache(maxsize=None)
def lcs(s1, s2, i=0, j=0):
    if i == len(s1) or j == len(s2):   # base case
        return 0
    if s1[i] == s2[j]:                  # chars match
        return 1 + lcs(s1, s2, i+1, j+1)
    return max(lcs(s1, s2, i+1, j),    # skip s1[i]
               lcs(s1, s2, i, j+1))    # skip s2[j]

print(lcs('ABCBDAB', 'BDCAB'))  # 4 (BCAB or BDAB)

# Overlapping subproblems — count how many times fib(3) is computed
call_count = {}

def fib_count(n):
    call_count[n] = call_count.get(n, 0) + 1
    if n <= 1: return n
    return fib_count(n-1) + fib_count(n-2)

fib_count(6)
print(call_count)
# {0:5, 1:8, 2:5, 3:3, 4:2, 5:1, 6:1}
# fib(3) called 3 times! Overlapping subproblems confirmed.

# Optimal substructure — shortest path
# If shortest path A→C goes through B, then:
#   path A→B must be the shortest A→B path
#   path B→C must be the shortest B→C path
import heapq

def dijkstra(graph, start):
    dist = {node: float('inf') for node in graph}
    dist[start] = 0
    heap = [(0, start)]
    while heap:
        d, u = heapq.heappop(heap)
        if d > dist[u]: continue
        for v, w in graph[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                heapq.heappush(heap, (dist[v], v))
    return dist

graph = {
    'A': [('B',1),('C',4)],
    'B': [('C',2),('D',5)],
    'C': [('D',1)],
    'D': []
}
print(dijkstra(graph, 'A'))  # {'A':0,'B':1,'C':3,'D':4}
